from pathlib import Path
import json,base64,zipfile,io,hashlib,re

ROOT=Path(__file__).resolve().parent
manifest=json.loads((ROOT/'varianten.json').read_text())
variants=[]
for variant in manifest['variants']:
    variant['html']=base64.b64encode((ROOT/variant['file']).read_bytes()).decode()
    variants.append(variant)

# The complete source archive is embedded in the comparison file so the saved
# deliverable preserves the original and both alternatives without dependencies.
buffer=io.BytesIO()
with zipfile.ZipFile(buffer,'w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted(ROOT.rglob('*')):
        if p.is_file() and '__pycache__' not in p.parts and p.name!='Christmann-Heise-Designvergleich.html':
            z.write(p,Path('christmann-heise-designs')/p.relative_to(ROOT))
archive=base64.b64encode(buffer.getvalue()).decode()

